// This file is generated by AI.

// 文档链接 (语句中的资源引用) 的目标解析: 只做 URI / 路径与文件类别的换算,
// 不依赖编辑器与应用状态, 便于单测。

import { kindFor, type FileKind } from '../lib/fileKind';
import { fromUri } from '../lib/uri';

/** 文档链接指向的文件 */
export interface LinkTarget {
  /** 项目内文件路径 */
  path: string;
  /** 文件类别, `scene` 表示场景脚本 */
  kind: FileKind;
}

/**
 * 解析文档链接的目标 URI。
 *
 * 场景脚本要按场景打开 (而非按资源预览), 其余资源按媒体类型进资源选项卡, 因此这里要给出类别。
 * 非 `file:` 协议 (如文档链接指向的 Web 链接) 不归编辑器处理, 返回 `null`。
 */
export function linkTargetOf(uri: string): LinkTarget | null {
  if (!uri.startsWith('file://')) return null;
  const path = fromUri(uri);
  if (!path) return null;
  if (path.replace(/\\/g, '/').toLowerCase().includes('/game/scene/')) return { path, kind: 'scene' };
  return { path, kind: kindFor(path) };
}
